import type { ErrorRequestHandler } from "express";
import multer from "multer";
import AppError from "../utils/app-error.js";

const errorHandler: ErrorRequestHandler = (
  err,
  _req,
  res,
  _next
) => {
  // Log the actual error for server-side debugging.
  console.error(err);

  // Handle errors generated by Multer during file uploads.
  if (err instanceof multer.MulterError) {
    const multerErrorMessages: Record<string, { message: string; statusCode: number }> = {
      LIMIT_FILE_SIZE: {
        message: "Uploaded file exceeds the allowed size.",
        statusCode: 413,
      },
      LIMIT_FILE_COUNT: {
        message: "Too many files uploaded.",
        statusCode: 400,
      },
      LIMIT_FIELD_COUNT: {
        message: "Too many form fields.",
        statusCode: 400,
      },
      LIMIT_FIELD_KEY: {
        message: "Form field name is too long.",
        statusCode: 400,
      },
      LIMIT_FIELD_VALUE: {
        message: "Form field value is too large.",
        statusCode: 400,
      },
      LIMIT_PART_COUNT: {
        message: "Too many multipart form parts.",
        statusCode: 400,
      },
      LIMIT_UNEXPECTED_FILE: {
        message: "Unexpected file field or too many files.",
        statusCode: 400,
      },
    };

    const errorDetails = multerErrorMessages[err.code];

    res.status(errorDetails?.statusCode ?? 400).json({
      success: false,
      message: errorDetails?.message ?? "Invalid file upload request.",
    });

    return;
  }

  // Handle errors intentionally created by our application.
  if (err instanceof AppError) {
    res.status(err.statusCode).json({
      success: false,
      message: err.message,
    });

    return;
  }

  // Handle unexpected errors safely.
  res.status(500).json({
    success: false,
    message: "Internal server error.",
  });
};

export default errorHandler;
